// Normalise keyword data from our API response
const resp = $input.first().json;
const kw = resp.data;
return [{
  json: {
    no_work: kw.no_work || false,
    _id: kw._id,
    keyword: String(kw.keyword || '').trim(),
    lsi_keywords: kw.lsi_keywords || '',
    target_word_count: parseInt(kw.target_word_count) || 1500,
    intent: kw.intent || 'Informational',
    cluster: kw.cluster || '',
    priority: kw.priority,
    image_alt_text: String(kw.image_alt_text || '').trim()
  }
}];

// Merge article HTML + SEO metadata into one object
const article = $('Generate Article').first().json.message.content;
const seoContent = $json.message.content;
const keyword = $('Normalise Keyword').first().json.keyword;
const keywordId = $('Normalise Keyword').first().json._id;
const sheetImageAlt = String($('Normalise Keyword').first().json.image_alt_text || '').trim();

let seo;
try {
  if (typeof seoContent === 'object' && seoContent !== null) {
    seo = seoContent;
  } else {
    const cleaned = String(seoContent).replace(/```json|```/g, '').trim();
    seo = JSON.parse(cleaned);
  }
} catch (e) {
  const kw = keyword || 'blog-post';
  seo = {
    meta_title: kw.substring(0, 60),
    meta_description: `Learn about ${kw}. A complete guide.`.substring(0, 160),
    slug: kw.toLowerCase().replace(/[^a-z0-9]+/g, '-').substring(0, 60),
    featured_image_alt: kw,
    image_search_query: kw,
    excerpt: kw
  };
}

function stripMarkdownFencesFromHtml(raw) {
  let html = String(raw || '').trim();
  if (html.charCodeAt(0) === 0xfeff) html = html.slice(1).trim();
  for (let i = 0; i < 8; i++) {
    const before = html;
    html = html.replace(/^["'`\s]+/, '').replace(/^```+[a-zA-Z0-9_-]*\s*/m, '').trim();
    if (html === before) break;
  }
  for (let i = 0; i < 8; i++) {
    const before = html;
    html = html.replace(/\s*```+\s*$/m, '').trim();
    if (html === before) break;
  }
  return html;
}

function stripLeakedLabel(s) {
  return String(s || '')
    .replace(/^pick next keyword\s*:\s*/i, '')
    .replace(/^keyword\s*:\s*/i, '')
    .trim();
}
seo.meta_title = stripLeakedLabel(seo.meta_title);

return [{
  json: {
    article_html: stripMarkdownFencesFromHtml(article),
    meta_title: seo.meta_title,
    meta_description: seo.meta_description,
    slug: seo.slug,
    image_search_query: seo.image_search_query,
    excerpt: seo.excerpt,
    keyword: keyword,
    keyword_id: keywordId,
    featured_image_alt: (sheetImageAlt || String(seo.featured_image_alt || '').trim() || keyword).slice(0, 500)
  }
}];

// Pick highest-res Pexels URL and pass it through with all article data
const fetch = $input.first().json;
const merge = $('Merge Article + Meta').first().json;
const photo = fetch.photos && fetch.photos[0];
const src = photo && photo.src;
const url = src && (src.original || src.large2x || src.large || src.medium || src.small) || '';
if (!url) {
  throw new Error('No Pexels image found for query: ' + (merge.image_search_query || merge.keyword));
}
return [{
  json: {
    ...merge,
    featured_image_url: url,
    pexels_photo_id: photo ? photo.id : null
  }
}];

// Build the final payload for the blog API
const d = $input.first().json;

function stripMarkdownFencesFromHtml(raw) {
  let html = String(raw || '').trim();
  if (html.charCodeAt(0) === 0xfeff) html = html.slice(1).trim();
  for (let i = 0; i < 8; i++) {
    const before = html;
    html = html.replace(/^["'`\s]+/, '').replace(/^```+[a-zA-Z0-9_-]*\s*/m, '').trim();
    if (html === before) break;
  }
  for (let i = 0; i < 8; i++) {
    const before = html;
    html = html.replace(/\s*```+\s*$/m, '').trim();
    if (html === before) break;
  }
  return html;
}

const heroImg = d.featured_image_url
  ? `<figure class='wp-block-image n8n-hero-thumb'><img src='${d.featured_image_url.replace(/'/g, "&#39;")}' alt='${(d.featured_image_alt || '').replace(/'/g, "&#39;")}' loading='lazy' decoding='async' /></figure>\n\n`
  : '';

return [{
  json: {
    title: d.meta_title,
    slug: d.slug || '',
    content: heroImg + stripMarkdownFencesFromHtml(d.article_html),
    excerpt: d.excerpt || '',
    meta_title: d.meta_title || '',
    meta_description: d.meta_description || '',
    keyword: d.keyword || '',
    keyword_ref: d.keyword_id || '',
    featured_image_url: d.featured_image_url || '',
    featured_image_alt: d.featured_image_alt || ''
  }
}];

